    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ConversionInfo conversionInfo:
                if (conversionInfo != ConversionInfo)
                {
                    ConversionInfo = conversionInfo;
                    ModifiedParameters[nameof(ConversionInfo)] = ConversionInfo;
                }
                
                return true;
            case CoordinateSegment coordinateSegments:
                CoordinateSegments ??= [];
                if (!CoordinateSegments.Contains(coordinateSegments))
                {
                    CoordinateSegments = [..CoordinateSegments, coordinateSegments];
                    ModifiedParameters[nameof(CoordinateSegments)] = CoordinateSegments;
                }
                
                return true;
            case SpatialReference spatialReference:
                if (spatialReference != SpatialReference)
                {
                    SpatialReference = spatialReference;
                    ModifiedParameters[nameof(SpatialReference)] = SpatialReference;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case ConversionInfo _:
                ConversionInfo = null;
                ModifiedParameters[nameof(ConversionInfo)] = ConversionInfo;
                return true;
            case CoordinateSegment coordinateSegments:
                CoordinateSegments = CoordinateSegments?.Where(c => c != coordinateSegments).ToList();
                ModifiedParameters[nameof(CoordinateSegments)] = CoordinateSegments;
                return true;
            case SpatialReference _:
                SpatialReference = null;
                ModifiedParameters[nameof(SpatialReference)] = SpatialReference;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        ConversionInfo?.ValidateRequiredGeneratedChildren();
        if (CoordinateSegments is not null)
        {
            foreach (CoordinateSegment child in CoordinateSegments)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        SpatialReference?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
